import { createClient } from 'npm:@supabase/supabase-js@2.116.0'
const cors={"Access-Control-Allow-Origin":"*","Access-Control-Allow-Headers":"authorization, x-client-info, apikey, content-type","Access-Control-Allow-Methods":"POST,OPTIONS"}
Deno.serve(async(req)=>{if(req.method==='OPTIONS')return new Response('ok',{headers:cors});try{const auth=req.headers.get('Authorization');if(!auth)throw new Error('Unauthorized');const client=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_PUBLISHABLE_KEY')!,{global:{headers:{Authorization:auth}}});const token=auth.replace(/^Bearer\s+/,'');const{data:{user},error}=await client.auth.getUser(token);if(error||!user)throw new Error('Unauthorized');const{user_id}=await req.json();if(typeof user_id!=='string')throw new Error('Invalid user');const admin=createClient(Deno.env.get('SUPABASE_URL')!,Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!);const{data:p}=await admin.from('profiles').select('id,is_active,moderation_status').eq('id',user_id).maybeSingle();if(!p||!p.is_active||['suspended','banned'].includes(p.moderation_status))throw new Error('Profile unavailable');const{data:blocked}=await admin.from('blocks').select('id').or(`and(blocker_id.eq.${user.id},blocked_id.eq.${user_id}),and(blocker_id.eq.${user_id},blocked_id.eq.${user.id})`).limit(1);if(blocked?.length)throw new Error('Blocked');const{data:photos,error:pe}=await admin.from('profile_photos').select('storage_path,sort_order,is_primary').eq('user_id',user_id).order('sort_order').limit(8);if(pe)throw pe;const urls=[];for(const photo of photos??[]){const{data:s,error:se}=await admin.storage.from('profile-photos').createSignedUrl(photo.storage_path,600);if(!se&&s?.signedUrl)urls.push({...photo,url:s.signedUrl})}return new Response(JSON.stringify({photos:urls}),{headers:{...cors,'Content-Type':'application/json'}})}catch(e){return new Response(JSON.stringify({error:e instanceof Error?e.message:'Request failed'}),{status:400,headers:{...cors,'Content-Type':'application/json'}})}})
